function loadState(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.companies))return hydrate(s)}catch(e){}return hydrate({companies:[],azure:DEFAULT_AZURE,createdAt:Date.now()})}
function hydrate(s){s.azure=Object.assign({},DEFAULT_AZURE,s.azure||{});s.azure.status=Object.assign({state:"none",message:""},s.azure.status||{});s.settings=Object.assign({},DEFAULT_SETTINGS,s.settings||{});if(!Array.isArray(s.settings.crawlPortals)||!s.settings.crawlPortals.length)s.settings.crawlPortals=DEFAULT_PORTALS();if(!s.settings.profiles||typeof s.settings.profiles!=="object"||!Object.keys(s.settings.profiles).length)s.settings.profiles=DEFAULT_PROFILES();if(!s.settings.activeProfile||!s.settings.profiles[s.settings.activeProfile])s.settings.activeProfile=Object.keys(s.settings.profiles)[0];if(!s.settings.learn||typeof s.settings.learn!=="object")s.settings.learn={guidance:[],termMap:{},negatives:[],positives:[]};s.companies=(s.companies||[]).map(normalizeCompany);return s}
function normalizeCompany(c){return Object.assign({company_id:"",company_name:"",website_url:"",legal_form:"",industry:"",nace_code:"",nace_label:"",employee_range:"",city:"",country:"",crm_revenue:0,raw_tags:[],tags:{manufacturers:[],technologies:[],business_areas:[]},evidence:[],crawl_status:"pending",last_crawled_at:"",opportunity_score:0,priority:"D",clusters:[],notes:"",source_text:"",ai_summary:"",ai_potential:"",firmographics:{},ai:{},fit:{}},c,{raw_tags:Array.isArray(c.raw_tags)?c.raw_tags:[],tags:Object.assign({manufacturers:[],technologies:[],business_areas:[]},c.tags||{}),evidence:Array.isArray(c.evidence)?c.evidence:[],firmographics:(c.firmographics&&typeof c.firmographics==="object")?c.firmographics:{},ai:(c.ai&&typeof c.ai==="object")?c.ai:{},fit:(c.fit&&typeof c.fit==="object")?c.fit:{}})}
